build.apps/custom-plan-demo/main.py:
from fastapi import FastAPI

app = FastAPI()


@app.get('/health')
def health():
    return {'ok': True}

build.infra/workload/custom.tf:
resource "google_storage_bucket" "uploads" {
  name                        = "${var.product_id}-uploads"
  location                    = var.region
  uniform_bucket_level_access = true
}

resource "google_storage_bucket_object" "seed" {
  for_each = toset([google_storage_bucket.uploads.url])
  name     = "seed.txt"
  bucket   = google_storage_bucket.uploads.name
  content  = "seed"
}

